import React from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const FAQ = () => {
  return (
    <div
      className="container-fluid"
      style={{
        backgroundColor: "#F8F9FA",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <h1>Perguntas Frequentes (FAQ)</h1>
      <div className="mt-4">
        <h4>1. Como me inscrevo nos cursos?</h4>
        <p>
          Depois de já ter feito o Registo, faça Login e assim que entrares no site, verás em destaque um botão azul de  
        </p>

        <h4>2. Os cursos são gratuitos?</h4>
        <p>
          Alguns cursos são gratuitos, enquanto outros possuem uma taxa de
          inscrição.
        </p>

        <h4>3. Como acessar as aulas ao vivo?</h4>
        <p>
          Dentro da plataforma, vá até a aba "Aulas" e clique na opção "Aulas ao
          Vivo".
        </p>

        <h4>4. Como faço para obter um certificado?</h4>
        <p>
          Após concluir um curso e passar na avaliação final, você poderá gerar
          seu certificado diretamente na plataforma.
        </p>
      </div>
    </div>
  );
};

export default FAQ;
